INSERT INTO "users" ("id", "name", "email", "emailVerified", "image", "role", "created_at", "updated_at", "deleted_at", "phone", "blocked_at", "blocked_by", "blocked_reason") VALUES ('catalog-import:wencel', 'Przemysław Wencel', 'catalog-import+wencel@modularhub.invalid', NULL, NULL, 'producer', '2026-10-26T10:26:32.534Z'::timestamptz, '2026-10-26T11:49:32.202Z'::timestamptz, NULL, '+48 000 000 000', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "producer" ("id", "user_id", "nip", "name", "country_code", "rating", "review_count", "technology", "verification_status", "created_at", "updated_at", "deleted_at", "production_scale", "inquiry_response_time_label", "showroom_visit_available", "showroom_visit_note", "description") VALUES ('e0030000-0000-4000-8000-000000000103', 'catalog-import:wencel', 'CATALOG-WENCEL', 'Przemysław Wencel', 'PL', NULL, 0, 'modulowa-stal-lekka', 'not_submitted', '2026-10-26T10:26:32.534Z'::timestamptz, '2026-10-26T11:49:32.202Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Producent domków na solidnej stalowej ramie, które można łatwo i wielokrotnie przenosić. Ściany w technologii szkieletowej z drewna konstrukcyjnego C-24 wypełnia się wybraną izolacją (piana PUR, wełna mineralna lub włókno drzewne), a elewację i wykończenie wnętrz dobiera się z kilku wariantów. Układ pomieszczeń ustala klient, a producent jest otwarty na jego propozycje.') ON CONFLICT DO NOTHING;
INSERT INTO "producer_delivery_country" ("producer_id", "country_code", "created_at") VALUES ('e0030000-0000-4000-8000-000000000103', 'PL', '2026-10-26T10:26:32.534Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_member" ("id", "producer_id", "user_id", "added_by", "created_at") VALUES ('a4da76ab-bc81-403f-b6de-7385c9a148b2', 'e0030000-0000-4000-8000-000000000103', 'catalog-import:wencel', NULL, '2026-10-26T10:26:32.534Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('4aef1a6b-7123-488b-8f15-9ad4fcfc4393', 'e0030000-0000-4000-8000-000000000103', 'en', 'Producer of cabins built on a solid steel frame that can be moved easily and repeatedly. Walls are timber frame in C-24 structural timber filled with the chosen insulation (PUR foam, mineral wool or wood fibre), and the facade and interior finish are chosen from several options. The client decides the room layout, and the producer is open to the client''s proposals.', NULL, NULL, '2026-10-26T10:26:32.534Z'::timestamptz, '2026-10-26T11:49:32.203Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('a26fc7c6-eaac-41fa-ba8f-fed48ed1fe40', 'e0030000-0000-4000-8000-000000000103', 'de', 'Hersteller von Ferienhäusern auf einem massiven Stahlrahmen, die sich leicht und wiederholt versetzen lassen. Die Wände in Holzrahmenbauweise aus Konstruktionsholz C-24 werden mit der gewählten Dämmung (PUR-Schaum, Mineralwolle oder Holzfaser) gefüllt, Fassade und Innenausbau werden aus mehreren Varianten gewählt. Die Raumaufteilung bestimmt der Kunde, der Hersteller ist für dessen Vorschläge offen.', NULL, NULL, '2026-10-26T10:26:32.534Z'::timestamptz, '2026-10-26T11:49:32.203Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "producer_translation" ("id", "producer_id", "locale", "description", "showroom_visit_note", "inquiry_response_time_label", "created_at", "updated_at") VALUES ('c6d60e73-8b0a-4486-8a35-027f87544a7e', 'e0030000-0000-4000-8000-000000000103', 'nl', 'Producent van huisjes op een stevig stalen frame die gemakkelijk en herhaaldelijk kunnen worden verplaatst. De wanden zijn houtskeletbouw van constructiehout C-24, gevuld met de gekozen isolatie (PUR-schuim, minerale wol of houtvezel); gevel en interieurafwerking kies je uit meerdere varianten. De klant bepaalt de indeling van de ruimtes en de producent staat open voor zijn voorstellen.', NULL, NULL, '2026-10-26T10:26:32.534Z'::timestamptz, '2026-10-26T11:49:32.203Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('9c87e504-8de5-4a64-ae6b-80e53fd60f7c', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', 'en', 'Feasibility and formal requirements depend on the specific plot and local regulations.', '2026-10-06T09:12:06.272Z'::timestamptz, '2026-10-06T09:12:06.272Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('770a3199-1d74-48f6-900a-257e3705d368', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', 'de', 'Realisierbarkeit und formale Anforderungen hängen vom konkreten Grundstück und den örtlichen Vorgaben ab.', '2026-10-06T09:12:06.272Z'::timestamptz, '2026-10-06T09:12:06.272Z'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "reference_text_translation" ("id", "source_pl", "locale", "translated", "created_at", "updated_at") VALUES ('eea7d9ec-ebb7-41fb-ae26-04cfba73092d', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', 'nl', 'Haalbaarheid en formele vereisten zijn afhankelijk van het specifieke perceel en de lokale voorschriften.', '2026-10-06T09:12:06.272Z'::timestamptz, '2026-10-06T09:12:06.272Z'::timestamptz) ON CONFLICT DO NOTHING;
